function cyl_y(cx,cy,cz,r,len,type){
  for(var x=cx-r;x<=cx+r;x++)for(var z=cz-r;z<=cz+r;z++){
    if((x-cx)*(x-cx)+(z-cz)*(z-cz)>r*r)continue;
    for(var y=cy;y<cy+len;y++)block(x,y,z,type);
  }
}
function cyl_x(cx,cy,cz,r,len,type){
